import{c as e,Q as o,j as r,m as n}from"./chunks/framework.DVkeSyfh.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),a={name:"guide/introduction.md"};function i(s,t,d,l,c,g){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Nikogin Framework is a lightweight, opinionated foundation for building WordPress plugins. It brings structure to plugin development by providing a service container, repository pattern, listener system, admin controllers, and a CLI — inspired by Laravel, designed for WordPress.</p><h2 id="what-it-provides" tabindex="-1">What it provides <a class="header-anchor" href="#what-it-provides" aria-label="Permalink to &quot;What it provides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>What you get</th></tr></thead><tbody><tr><td><strong>Architecture</strong></td><td>Service container, service providers, bootstrap lifecycle</td></tr><tr><td><strong>Database</strong></td><td>Repository pattern for custom tables, post types, and taxonomies</td></tr><tr><td><strong>WordPress</strong></td><td>Listeners for actions/filters, jobs, shortcodes, admin controllers</td></tr><tr><td><strong>HTTP</strong></td><td>REST API controllers and routing</td></tr><tr><td><strong>Frontend</strong></td><td>Vite-based asset pipeline with TypeScript and SCSS</td></tr><tr><td><strong>Console</strong></td><td><code>php nikogin make:*</code> commands to scaffold any class</td></tr></tbody></table><h2 id="two-packages" tabindex="-1">Two packages <a class="header-anchor" href="#two-packages" aria-label="Permalink to &quot;Two packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Composer name</th><th>Role</th></tr></thead><tbody><tr><td><strong>Framework</strong></td><td><code>nikoginwp/framework</code></td><td>Abstractions, support classes, console commands</td></tr><tr><td><strong>Nikogin</strong></td><td><code>nikoginwp/nikogin</code></td><td>Plugin skeleton — bootstraps, managers, routes, config</td></tr></tbody></table><p>The <strong>framework</strong> is the engine. The <strong>nikogin</strong> skeleton is the starting point for every new plugin.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>PHP <strong>8.3+</strong></li><li>WordPress <strong>6.0+</strong></li><li>Composer</li><li>Node <strong>20+</strong> (for frontend)</li></ul>',9)])])}const u=e(a,[["render",i]]);export{h as __pageData,u as default};
